{
  "@context": {
    "@language": "en",
    "@vocab": "https://schema.org/",
    "cr": "http://mlcommons.org/croissant/",
    "dct": "http://purl.org/dc/terms/",
    "sc": "https://schema.org/"
  },
  "@type": "cr:TaskProblem",
  "conformsTo": "http://mlcommons.org/croissant/1.0",
  "@id": "fair-robust-ai-face-detection-task",
  "name": "Fair and Robust AI-Generated Face Detection",
  "description": "Develop machine learning models to detect AI-generated faces while ensuring fairness and robustness across demographic groups.",
  "paper_id": "[FILL IN THE BLANK: paper identifier]",

  "cr:input": [
    {
      "@type": "cr:FileObject",
      "name": "AI-Face Dataset",
      "description": "A large-scale image dataset with demographic annotations. Contains 1,646,545 face images, including 1,245,660 AI-generated and 400,885 real images. Each image is associated with demographic attributes (skin tone, gender, age), generation method, and a binary label (real or fake). Images are preprocessed (cropped, resized, augmented). Example: Image with skin tone = 5, gender = 1 (Male), age = 2 (Adult), generation method = GAN, real vs. fake = 1 (fake).",
      "encodingFormat": "image/jpeg, text/csv",
      "contentUrl": "[FILL IN THE BLANK: dataset download URL]"
    }
  ],

  "cr:output": {
    "name": "predictions",
    "description": "Predictions include a binary label for real vs. fake classification and demographic attribute predictions (skin tone, gender, age). Example: real_vs_fake = 1 (fake), skin_tone = 5, gender = 1 (Male), age = 2 (Adult).",
    "cr:schema": {
      "@type": "cr:RecordSet",
      "name": "prediction_schema",
      "field": [
        {
          "@type": "cr:Field",
          "name": "real_vs_fake",
          "dataType": "sc:Boolean",
          "description": "Binary label indicating whether the face is real (0) or AI-generated (1). Example: 1."
        },
        {
          "@type": "cr:Field",
          "name": "skin_tone",
          "dataType": "sc:Integer",
          "description": "Skin tone annotated using the Monk Skin Tone Scale (1–10). Example: 5."
        },
        {
          "@type": "cr:Field",
          "name": "gender",
          "dataType": "sc:Integer",
          "description": "Binary gender label (Male = 1, Female = 0). Example: 1."
        },
        {
          "@type": "cr:Field",
          "name": "age",
          "dataType": "sc:Integer",
          "description": "Age category: Child = 0, Youth = 1, Adult = 2, Middle-age Adult = 3, Senior = 4. Example: 2."
        }
      ]
    }
  },

  "cr:implementation": {
    "cr:environment": {
      "language": "Python",
      "packages": ["torch", "torchvision", "numpy", "pandas", "scikit-learn", "[FILL IN THE BLANK: other required packages]"]
    },
    "entryPoint": "solution.py",
    "interface": "predict(input_dir, output_dir)"
  },

  "cr:evaluation": {
    "primaryMetric": "Area Under the ROC Curve (AUC), Fairness Equal Opportunity (FEO)",
    "metrics": [
      "Area Under the ROC Curve (AUC)",
      "Accuracy (ACC)",
      "Average Precision (AP)",
      "Equal Error Rate (EER)",
      "False Positive Rate (FPR)",
      "Demographic Parity (FDP)",
      "Fairness Equal Opportunity (FEO)",
      "Fairness Overall Accuracy Equality (FOAE)",
      "Fairness Maximum Equal Opportunity (FMEO)",
      "Fairness Individual Disparity (FIND)"
    ],
    "higherIsBetter": true,
    "notes": "Metrics are stratified by demographic subgroups (e.g., skin tone, gender, age) and intersectional groups (e.g., Female-Light, Male-Dark). Results are averaged over 5 random samplings of the dataset. For fairness metrics like FEO, lower values are better."
  },

  "cr:execution": {
    "runtimeLimitSec": 600,
    "memoryLimitMb": 4096,
    "allowedExternalData": "unknown"
  },

  "open_questions": [
    "What is the exact paper identifier?",
    "What is the dataset download URL?",
    "What are the exact versions of required Python packages?",
    "What are the specific runtime and memory limits for the task?",
    "Are participants allowed to use external data for training?"
  ],

  "fill_in_the_blank": [
    "paper_id - reason it could not be determined from the paper",
    "cr:input[0].contentUrl - reason it could not be determined from the paper",
    "cr:implementation.cr:environment.packages[4] - reason it could not be determined from the paper",
    "cr:execution.runtimeLimitSec - defaulted to 600 as not specified in the paper",
    "cr:execution.memoryLimitMb - defaulted to 4096 as not specified in the paper",
    "cr:execution.allowedExternalData - reason it could not be determined from the paper"
  ]
}
